import{_ as t,c as a,o as l,a2 as o}from"./chunks/framework.CzULAunO.js";const m=JSON.parse('{"title":"网络空间安全————浏览网站安全","description":"","frontmatter":{},"headers":[],"relativePath":"docs/general-skills/cyber security/password_manage2.md","filePath":"docs/general-skills/cyber security/password_manage2.md","lastUpdated":1766652908000}'),i={name:"docs/general-skills/cyber security/password_manage2.md"};function r(s,e,c,d,n,h){return l(),a("div",null,e[0]||(e[0]=[o('<h1 id="网络空间安全————浏览网站安全" tabindex="-1">网络空间安全————浏览网站安全 <a class="header-anchor" href="#网络空间安全————浏览网站安全" aria-label="Permalink to &quot;网络空间安全————浏览网站安全&quot;">​</a></h1><hr><h2 id="https-与-http" tabindex="-1">https:// 与 http:// <a class="header-anchor" href="#https-与-http" aria-label="Permalink to &quot;https:// 与 http://&quot;">​</a></h2><h3 id="什么是-https" tabindex="-1">什么是 HTTPS？ <a class="header-anchor" href="#什么是-https" aria-label="Permalink to &quot;什么是 HTTPS？&quot;">​</a></h3><ul><li>HTTPS 是一种在 Web 服务器和 Web 浏览器之间发送数据的安全方式。</li></ul><p>超文本传输协议安全 (HTTPS) 是 HTTP 的安全版本，HTTP 是用于在 Web 浏览器和网站之间发送数据的主要协议。HTTPS 经过加密，以提高数据传输的安全性。当用户传输敏感数据（例如通过登录银行账户、电子邮件服务或健康保险提供商）时，这一点尤其重要。 任何网站都应使用 HTTPS，尤其是那些需要登录凭据的网站。在现代 Web 浏览器（例如 Chrome）中，未使用 HTTPS 的网站与使用 HTTPS 的网站的标记有所不同。URL 栏中如出现挂锁，则表示该网页是安全的。Web 浏览器非常重视 HTTPS；<a href="https://www.cloudflare.com/learning/ssl/why-use-https/" target="_blank" rel="noreferrer">Google Chrome 和其他浏览器将所有非 HTTPS 网站标记为不安全。</a><img src="https://github.com/user-attachments/assets/7903824d-137b-4ceb-80d0-81325bbf5877" alt="image"></p><h3 id="https-为什么很重要-如果网站没有-https-那会如何" tabindex="-1">HTTPS 为什么很重要？如果网站没有 HTTPS，那会如何？ <a class="header-anchor" href="#https-为什么很重要-如果网站没有-https-那会如何" aria-label="Permalink to &quot;HTTPS 为什么很重要？如果网站没有 HTTPS，那会如何？&quot;">​</a></h3><p>HTTPS 阻止网站以任何在网络上窥探的人都能轻松查看的方式广播信息。通过常规 HTTP 发送信息时，信息会分解为数据包，使用免费软件即可轻松“嗅探”这些数据包。这使得通过不安全的媒介（例如公共 Wi-Fi）进行的通信极易受到拦截。实际上，所有通过 HTTP 进行的通信都是以纯文本形式进行的，因而能够为任何使用正确工具的人轻松访问，而且容易遭受在途攻击。</p><p>使用 HTTPS 时，流量会经过加密，即使嗅探到数据包或以其他方式截取数据包，它们也会呈现为无意义的字符。我们来看一个例子：</p><blockquote><ul><li>加密前：</li></ul></blockquote><p><code>这是完全可读的文本字符串</code></p><blockquote><ul><li>加密后：</li></ul></blockquote><p><code>ITM0IRyiEhVpa6VnKyExMiEgNveroyWBPlgGyfkflYjDaaFf/Kn3bo3OfghBPDWo6AfSHlNtL8N7ITEwIXc1gU5X73xMsJormzzXlwOyrCs+9XCPk63Y+z0=</code></p><h3 id="http-为什么不安全" tabindex="-1">HTTP 为什么不安全 <a class="header-anchor" href="#http-为什么不安全" aria-label="Permalink to &quot;HTTP 为什么不安全&quot;">​</a></h3><ul><li>HTTP 由于是明文传输，主要存在三大风险</li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:center;"></th></tr></thead><tbody><tr><td style="text-align:center;">1、窃听风险 <br> 中间人可以获取到通信内容，由于内容是明文，所以获取明文后有安全风险</td><td style="text-align:center;"><img src="https://github.com/user-attachments/assets/90d82d50-8d3c-4c7d-9f9b-e8b55ce89fb7" alt="image"></td></tr><tr><td style="text-align:center;">2、篡改风险 <br> 中间人可以篡改报文内容后再发送给对方，风险极大</td><td style="text-align:center;"><img src="https://github.com/user-attachments/assets/3ba95012-58be-4132-b9bd-31cda09bed3f" alt="image"></td></tr><tr><td style="text-align:center;">3、冒充风险 <br> 比如你以为是在和某宝通信，但实际上是在和一个钓鱼网站通信。</td><td style="text-align:center;"><img src="https://github.com/user-attachments/assets/1807e749-aa5d-4c5c-a21e-f1b342ef8a02" alt="image"></td></tr></tbody></table><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>增强安全性：HTTPS 通过 SSL/TLS 协议对数据进行加密，保护用户数据不被窃取或篡改，确保通信的安全性。</p><p>提升信任度：使用 HTTPS 的网站更受用户信赖，因为它表明网站采取了额外的安全措施来保护用户隐私和数据。</p><p>浏览器支持：现代浏览器如 Chrome 将 HTTP 网站标记为“不安全”，而 HTTPS 网站则不会，这影响了用户对网站安全性的感知。</p><p>搜索引擎优化：搜索引擎倾向于提升使用 HTTPS 的网站的搜索排名，因为它们被认为是更安全、更可靠的资源。</p><hr><h2 id="常见域名" tabindex="-1">常见域名 <a class="header-anchor" href="#常见域名" aria-label="Permalink to &quot;常见域名&quot;">​</a></h2><h2 id="域名-domain-name" tabindex="-1">域名（Domain Name） <a class="header-anchor" href="#域名-domain-name" aria-label="Permalink to &quot;域名（Domain Name）&quot;">​</a></h2><p>是互联网上用来识别和访问网站的一个易于记忆的地址。它将 IP 地址（一串数字）转换为人类可读的格式，比如 &lt;www.example.com。域名系统（DNS）负责将域名解析为对应的&gt; IP 地址，以便用户的设备能够找到并访问相应的服务器。 顶级域名（Top-Level Domain, TLD）： </p><p><img src="https://github.com/user-attachments/assets/29a37ddd-379c-452d-98c4-1e7b43bce374" alt="image"></p><hr><h3 id="子域名-subdomain" tabindex="-1">子域名（Subdomain） <a class="header-anchor" href="#子域名-subdomain" aria-label="Permalink to &quot;子域名（Subdomain）&quot;">​</a></h3><p>位于域名的最左侧部分，可以自定义。例如，在 subdomain.example.com 中，subdomain 就是子域名。 二级域名（Second-Level Domain, SLD）：</p><p>紧随子域名之后，通常是注册时选择的主要域名部分。例如，在 example.com 中，example 是二级域名。 顶级域名（Top-Level Domain, TLD）：</p><p>位于域名的最右侧部分，分为两类： 通用顶级域名（Generic Top-Level Domains, gTLDs）：如.com、.org、.net 等。 国家代码顶级域名（Country Code Top-Level Domains, ccTLDs）：如.cn（中国）、.us（美国）、.uk（英国）等。 根域名（Root Domain）：</p><p>根域名是域名层次结构的最顶层，用。表示，但不在域名中显示。例如，example.com.实际上是 example.com。</p><p>一个完整的域名示例是<code>www.example.com</code> ，其结构如下：</p><blockquote><ul><li>www：子域名</li><li>example：二级域名</li><li>com：顶级域名</li></ul></blockquote><hr><ol><li><p><strong>域名的合法性</strong>：</p><ul><li>域名的合法性涉及到域名是否按照 ICANN（互联网名称与数字地址分配机构）的规定进行注册和使用，以及是否遵守了相关的法律法规。</li><li>合法的域名不会侵犯他人的商标权、版权或其他知识产权。</li><li>合法性还意味着域名的注册和使用没有违反任何国家或地区的法律，例如，没有用于非法活动或欺诈行为。</li></ul></li><li><p><strong>域名的完整性</strong>：</p><ul><li>完整性指的是域名是否完整且正确，没有拼写错误或遗漏的部分。</li><li>一个完整的域名应该包括所有的子域名和顶级域名（TLD），例如 <code>www.example.com</code>。</li><li>完整性还涉及到域名是否正确地指向了预期的服务器或网站，没有被错误地重定向到其他网站。</li></ul></li><li><p><strong>顶级域名（TLD）</strong>：</p><ul><li>顶级域名是域名结构中的最后一部分，如 <code>.com</code>、<code>.org</code>、<code>.net</code> 等。</li><li>TLD 分为几种类型，包括通用顶级域名（gTLDs）如 <code>.com</code>、<code>.net</code>，以及国家代码顶级域名（ccTLDs）如 <code>.uk</code>、<code>.de</code>。</li><li>TLD 可以提供关于网站性质和目的的信息，例如 <code>.gov</code> 通常用于政府网站，<code>.edu</code> 用于教育机构。</li></ul></li><li><p><strong>子域名</strong>：</p><ul><li>子域名是主域名的一个分支，用于指向同一主域名下的不同部分或服务。</li><li>例如，在 <code>mail.example.com</code> 中，<code>mail</code> 是一个子域名，用于指向该域的邮件服务。</li><li>子域名的使用可以帮助组织网站内容，但也可能导致安全问题，如子域名劫持。</li></ul></li><li><p><strong>国别域名</strong>：</p><ul><li>国别域名是特定国家的顶级域名，如 <code>.uk</code>（英国）、<code>.de</code>（德国）等。</li><li>这些域名通常用于标识网站的地理位置和目标受众，有助于用户识别与自己地区相关的网站。</li><li>国别域名也可以用于表示网站内容的语言或文化背景。</li></ul></li><li><p><strong>混合域名</strong>：</p><ul><li>混合域名是指那些故意将字母和数字混合使用的域名，以模仿知名品牌或网站。</li><li>例如，将知名品牌的域名中的某个字母替换为相似的数字（如将 &quot;e&quot; 替换为 &quot;3&quot;），以欺骗用户。</li><li>这种域名通常用于钓鱼攻击，目的是诱使用户输入敏感信息，如用户名和密码。</li></ul></li></ol><h2 id="最后总结" tabindex="-1">最后总结 <a class="header-anchor" href="#最后总结" aria-label="Permalink to &quot;最后总结&quot;">​</a></h2><p><strong>需注意以下几点：1. 核实域名的合法性和完整性，避免拼写错误或遗漏。2. 识别顶级域名（TLD），区分通用和国别域名。3. 警惕子域名和混合域名，防范钓鱼网站。4. 使用 HTTPS 协议，确保数据传输安全。5. 检查域名 WHOIS 信息，确认注册人和注册日期。6. 使用安全工具检测域名声誉，避免访问有不良记录的网站。简而言之，用户应保持警惕，仔细检查域名，以确保网络安全。</strong></p><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><p><a href="https://cloud.tencent.com/developer/article/1758154" target="_blank" rel="noreferrer">https://cloud.tencent.com/developer/article/1758154</a></p><p><a href="https://www.cloudflare.com/zh-cn/learning/ssl/what-is-https/" target="_blank" rel="noreferrer">https://www.cloudflare.com/zh-cn/learning/ssl/what-is-https/</a></p>',41)]))}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
